public class TextAreaLineCounterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String labelText(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            TextAreaLineCounter panel = new TextAreaLineCounter();
            java.awt.Component areaComp = find(panel, "notes");
            java.awt.Component labelComp = find(panel, "lineCount");
            check("notes area found", true, areaComp instanceof javax.swing.JTextArea);
            check("label shows zero at startup", "Lines: 0", labelText(labelComp));
            if (areaComp instanceof javax.swing.JTextArea) {
                javax.swing.JTextArea notes = (javax.swing.JTextArea) areaComp;
                notes.setText("alpha");
                check("single line count", 1, panel.countLines());
                check("single line label", "Lines: 1", labelText(labelComp));
                notes.setText("alpha\nbeta\ngamma");
                check("three lines", 3, panel.countLines());
                notes.setText("alpha\n");
                check("trailing newline does not add a line", 1, panel.countLines());
                notes.setText("alpha\n\n");
                check("blank line in the middle counts", 2, panel.countLines());
                notes.setText("");
                check("empty area label", "Lines: 0", labelText(labelComp));
            } else {
                failures++;
                System.out.println("FAIL  notes area not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

