import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;

public class TextAreaLineCounter extends JPanel {

    private final JTextArea notes = new JTextArea(6, 20);
    private final JLabel lineCount = new JLabel("Lines: ?");

    public TextAreaLineCounter() {
        notes.setName("notes");
        lineCount.setName("lineCount");
        add(notes);
        add(lineCount);
        notes.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent e) {
                refreshLabel();
            }

            public void removeUpdate(DocumentEvent e) {
                refreshLabel();
            }

            public void changedUpdate(DocumentEvent e) {
                refreshLabel();
            }
        });
        refreshLabel();
    }

    public int countLines() {
        String text = notes.getText();
        if (text.isEmpty()) {
            return 0;
        }
        if (text.endsWith("\n")) {
            text = text.substring(0, text.length() - 1);
        }
        int lines = 1;
        for (int i = 0; i < text.length(); i++) {
            if (text.charAt(i) == '\n') {
                lines++;
            }
        }
        return lines;
    }

    public void refreshLabel() {
        lineCount.setText("Lines: " + countLines());
    }
}
